<script>
  import Markdown from '../Markdown/Markdown.svelte'

  /**
   * @typedef {object} FieldMetaProps
   * @property {string} id Id of the field
   * @property {string} [label]
   * @property {boolean} [labelVisible]
   * @property {string | null} [hint]
   * @property {string | null} [error]
   * @property {string} [labelClass]
   * @property {string} [hintClass]
   * @property {string} [errorClass]
   */

  /** @type {FieldMetaProps} */
  let {
    id,
    label = '',
    labelVisible = true,
    hint = null,
    error = null,
    labelClass,
    hintClass,
    errorClass,
  } = $props()
</script>

<!-- input-meta is deprecated in favour of field-meta, and goes in the next major -->
{#if label && labelVisible}
  <label class="label field-meta input-meta {labelClass}" for={id}>
    <Markdown content={label} inline />
  </label>
{/if}
{#if hint}
  <div id="{id}-hint" class="hint field-meta input-meta {hintClass}">
    <Markdown content={hint} inline />
  </div>
{/if}
<output
  id="{id}-error"
  class="error field-meta input-meta {errorClass}"
  class:sr-only={!error}
  for={id}
  role="alert"
>
  {#if error}
    <Markdown content={error} inline />
  {/if}
</output>
